import heapq

def a_star(start={{start}}, goal={{goal}}, neighbors={{neighbors_fn}}, h={{heuristic_fn}}):
    open_set = [(h(start, goal), 0, start, None)]
    came = {}; g_score = {start: 0}
    while open_set:
        f, g, cur, parent = heapq.heappop(open_set)
        if cur in came: continue
        came[cur] = parent
        if cur == goal:
            path = [cur]
            while came[path[-1]] is not None: path.append(came[path[-1]])
            return path[::-1], g
        for nb, w in neighbors(cur):
            ng = g + w
            if ng < g_score.get(nb, float('inf')):
                g_score[nb] = ng
                heapq.heappush(open_set, (ng + h(nb, goal), ng, nb, cur))
    return None, float('inf')
